@RestController
public class AsyncController {

    @GetMapping("/process")
    public Callable<String> processAsync() {
        return () -> {
            Thread.sleep(2000); // simulate delay
            return "Processed asynchronously";
        };
    }
}

@RestController
public class AsyncServiceController {

    @Autowired
    private AsyncService service;

    @GetMapping("/async-call")
    public CompletableFuture<String> callAsyncService() {
        return service.performTask();
    }
}

@Service
public class AsyncService {

    @Async
    public CompletableFuture<String> performTask() {
        // Simulate delay
        try { Thread.sleep(2000); } catch (InterruptedException ignored) {}
        return CompletableFuture.completedFuture("Done");
    }
}

@Configuration
@EnableAsync
public class AsyncExecutorConfig {

    @Bean(name = "taskExecutor")
    public Executor taskExecutor() {
        ThreadPoolTaskExecutor executor = new ThreadPoolTaskExecutor();
        executor.setCorePoolSize(4);
        executor.setMaxPoolSize(10);
        executor.setQueueCapacity(500);
        executor.setThreadNamePrefix("Async-");
        executor.initialize();
        return executor;
    }
}

@Async
public CompletableFuture<String> process() {
    return CompletableFuture.supplyAsync(() -> {
        throw new RuntimeException("Something went wrong");
    }).exceptionally(ex -> "Error: " + ex.getMessage());
}

@GetMapping("/deferred")
public DeferredResult<String> handleDeferred() {
    DeferredResult<String> output = new DeferredResult<>();
    new Thread(() -> {
        try {
            Thread.sleep(2000);
            output.setResult("Completed with DeferredResult");
        } catch (InterruptedException e) {
            output.setErrorResult("Error occurred");
        }
    }).start();
    return output;
}

public CompletableFuture<String> chainAsyncTasks() {
    return CompletableFuture.supplyAsync(() -> "Task1")
            .thenApply(result -> result + " + Task2")
            .thenApply(result -> result + " + Task3");
}

public CompletableFuture<String> runInParallel() {
    CompletableFuture<String> task1 = CompletableFuture.supplyAsync(() -> "First");
    CompletableFuture<String> task2 = CompletableFuture.supplyAsync(() -> "Second");

    return task1.thenCombine(task2, (a, b) -> a + " and " + b);
}

@RestController
@RequestMapping("/customers")
public class CustomerController {

    @Autowired
    private CustomerService customerService;

    @GetMapping("/{id}")
    public CompletableFuture<ResponseEntity<Customer>> getCustomer(@PathVariable Long id) {
        return customerService.findCustomerAsync(id)
               .thenApply(ResponseEntity::ok);
    }
}

@Service
public class CustomerService {

    @Autowired
    private CustomerRepository repo;

    @Async
    public CompletableFuture<Customer> findCustomerAsync(Long id) {
        return CompletableFuture.completedFuture(repo.findById(id).orElseThrow());
    }
}

